ation": "Fix δ>0.", "from_inputs": [], "from_local": [], "objects": []}, {"symbol": "ε", "type": "real number", "scope": "R004/argument", "start": "S001", "end": "S005", "kind": "arbitrary", "declaration": "Fix ε>0, to be sent to zero.", "from_inputs": [], "from_local": [], "objects": []}, {"symbol": "c", "type": "extended nonnegative real number", "scope": "R004/argument", "start": "S001", "end": "S005", "kind": "definition", "declaration": "Define c=Hscale(s,δ,E).", "from_inputs": [], "from_local": [], "objects": ["Hscale", "s", "δ", "E"]}, {"symbol": "V", "type": "sequence of subsets of ℝ^{n+1}", "scope": "R004/arbitrary-cover", "start": "S002", "end": "S005", "kind": "arbitrary", "declaration": "Take any countable δ-cover V of F, allowing empty padding members.", "from_inputs": [], "from_local": [], "objects": ["n", "δ", "F"]}, {"symbol": "ρ", "type": "sequence of finite nonnegative real numbers", "scope": "R004/arbitrary-cover", "start": "S002", "end": "S005", "kind": "definition", "declaration": "Define ρ_i=diam V_i; since V is a δ-cover, 0≤ρ_i≤δ.", "from_inputs": [], "from_local": [], "objects": ["V", "δ"]}, {"symbol": "A_i", "type": "sequence of subsets of ℝ^n", "scope": "R004/arbitrary-cover", "start": "S002", "end": "S005", "kind": "definition", "declaration": "Define A_i as the projection of V_i onto ℝ^n.", "from_inputs": [], "from_local": [], "objects": ["V", "n"]}, {"symbol": "B_i", "type": "sequence of subsets of ℝ", "scope": "R004/arbitrary-cover", "start": "S002", "end": "S005", "kind": "definition", "declaration": "Define B_i as the last-coordinate projection of V_i.", "from_inputs": [], "from_local": [], "objects": ["V"]}, {"symbol": "η", "type": "sequence of positive real numbers", "scope": "R004/arbitrary-cover", "start": "S002", "end": "S005", "kind": "definition", "declaration": "Define η_i=ε2^{-i-1}/(1+ρ_i^s).", "from_inputs": [], "from_local": [], "objects": ["ε", "ρ", "s"]}, {"symbol": "J", "type": "sequence of open subsets of ℝ, each empty 